#include "kernel_operator.h"
#include "lib/matmul_intf.h"

using namespace AscendC;

constexpr MatmulApiStaticTiling DYNAMIC_TILING = {
 .usedCoreNum = -1, .M = -1, .N = -1, .Ka = -1, .Kb = -1,
 .singleCoreM = -1, .singleCoreN = -1, .singleCoreK = -1,
 .baseM = 128, .baseN = 128, .baseK = 64,
 .depthA1 = -1, .depthB1 = -1, .stepM = -1, .stepN = -1,
 .isBias = 0, .transLength = -1, .iterateOrder = -1,
 .shareMode = -1, .shareL1Size = -1, .shareL0CSize = -1, .shareUbSize = -1,
 .stepKa = -1, .stepKb = -1, .depthAL1CacheUB = -1, .depthBL1CacheUB = -1,
 .dbL0A = -1, .dbL0B = -1, .dbL0C = 1,
 .ALayoutInfoB = -1, .ALayoutInfoS = -1, .ALayoutInfoN = -1, .ALayoutInfoG = -1, .ALayoutInfoD = -1,
 .BLayoutInfoB = -1, .BLayoutInfoS = -1, .BLayoutInfoN = -1, .BLayoutInfoG = -1, .BLayoutInfoD = -1,
 .CLayoutInfoB = -1, .CLayoutInfoS1 = -1, .CLayoutInfoN = -1, .CLayoutInfoG = -1, .CLayoutInfoS2 = -1,
 .BatchNum = -1, .mxTypePara = -1, .cfg = CFG_NORM
};

class KernelMatmul {
public:
 using A_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
 using B_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
 using C_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
 using BIAS_TYPE = MatmulType<TPosition::GM, CubeFormat::ND, half, false>;
 AscendC::Matmul<A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, DYNAMIC_TILING> mm;
 GlobalTensor<half> gmA;
 GlobalTensor<half> gmB;
 GlobalTensor<half> gmC;
 TPipe pipe;

 __aicore__ inline KernelMatmul() {}
 __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tilingGM) {
  gmA.SetGlobalBuffer((__gm__ half*)a);
  gmB.SetGlobalBuffer((__gm__ half*)b);
  gmC.SetGlobalBuffer((__gm__ half*)c);
  mm.Init(reinterpret_cast<__gm__ TCubeTiling*>(tilingGM), &pipe);
  mm.SetTensorA(gmA);
  mm.SetTensorB(gmB);
 }
 __aicore__ inline void Process() {
  mm.IterateAll(gmC);
 }
};

extern "C" __global__ __aicore__ void matmul_custom(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tilingGM) {
 KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIC_ONLY);
 KernelMatmul kernel;
 kernel.Init(a, b, c, tilingGM);
 kernel.Process();
}

#include <ATen/ATen.h>
#include <torch/library.h>
