#pragma pack(push, 4)
struct TCubeTiling {
    int32_t usedCoreNum = 0;
    int32_t M = 0;
    int32_t N = 0;
    int32_t Ka = 0;
    int32_t Kb = 0;
    int32_t singleCoreM = 0;
    int32_t singleCoreN = 0;
    int32_t singleCoreK = 0;
    int32_t baseM = 0;
    int32_t baseN = 0;
    int32_t baseK = 0;
    int32_t depthA1 = 0;
    int32_t depthB1 = 0;
    int32_t stepM = 0;
    int32_t stepN = 0;
    int32_t isBias = 0;
    int32_t transLength = 0;
    int32_t iterateOrder = 0;
    int32_t shareMode = 0;
    int32_t shareL1Size = 0;
    int32_t shareL0CSize = 0;
    int32_t shareUbSize = 0;
    int32_t batchM = 0;
    int32_t batchN = 0;
    int32_t singleBatchM = 0;
    int32_t singleBatchN = 0;
    int32_t stepKa = 0;
    int32_t stepKb = 0;
    int32_t depthAL1CacheUB = 0;
    int32_t depthBL1CacheUB = 0;
    int32_t dbL0A = 0;
    int32_t dbL0B = 0;
    int32_t dbL0C = 0;
    int32_t ALayoutInfoB = 0;
    int32_t ALayoutInfoS = 0;
    int32_t ALayoutInfoN = 0;
    int32_t ALayoutInfoG = 0;
    int32_t ALayoutInfoD = 0;
    int32_t BLayoutInfoB = 0;
    int32_t BLayoutInfoS = 0;
    int32_t BLayoutInfoN = 0;
    int32_t BLayoutInfoG = 0;
    int32_t BLayoutInfoD = 0;
    int32_t CLayoutInfoB = 0;
    int32_t CLayoutInfoS1 = 0;
    int32_t CLayoutInfoN = 0;
    int32_t CLayoutInfoG = 0;
    int32_t CLayoutInfoS2 = 0;
    int32_t BatchNum = 0;
    int32_t mxTypePara = 0;
};
#pragma pack(pop)

namespace ascendc_path {

at::Tensor run_matmul_custom(const at::Tensor &a, const at::Tensor &b)
{
    int64_t M = a.size(0);
    int64_t N = b.size(1);
    int64_t K = a.size(1);
    auto c = at::empty({M, N}, a.options());

    constexpr int32_t baseM = 128;
    constexpr int32_t baseN = 128;
    constexpr int32_t baseK = 64;

    int32_t singleCoreM = (M + baseM - 1) / baseM * baseM;
    int32_t singleCoreN = (N + baseN - 1) / baseN * baseN;
    int32_t singleCoreK = (K + baseK - 1) / baseK * baseK;
    if (singleCoreM == 0) singleCoreM = baseM;
    if (singleCoreN == 0) singleCoreN = baseN;
    if (singleCoreK == 0) singleCoreK = baseK;

    int32_t coreM = (M + singleCoreM - 1) / singleCoreM;
    int32_t coreN = (N + singleCoreN - 1) / singleCoreN;
    int32_t usedCoreNum = coreM * coreN;
    if (usedCoreNum > 8) usedCoreNum = 8;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int32_t stepM = singleCoreM / baseM;
    int32_t stepN = singleCoreN / baseN;
    int32_t stepKa = (singleCoreK + baseK - 1) / baseK;
    int32_t stepKb = stepKa;
    int32_t depthA1 = stepM * stepKa;
    int32_t depthB1 = stepN * stepKb;

    TCubeTiling tiling;
    memset(&tiling, 0, sizeof(TCubeTiling));
    tiling.usedCoreNum = usedCoreNum;
    tiling.M = M;
    tiling.N = N;
    tiling.Ka = K;
    tiling.Kb = K;
    tiling.singleCoreM = singleCoreM;
    tiling.singleCoreN = singleCoreN;
    tiling.singleCoreK = singleCoreK;
    tiling.baseM = baseM;
    tiling.baseN = baseN;
    tiling.baseK = baseK;
    tiling.depthA1 = depthA1;
    tiling.depthB1 = depthB1;
    tiling.stepM = stepM;
    tiling.stepN = stepN;
    tiling.isBias = 0;
    tiling.iterateOrder = 0;
    tiling.shareL0CSize = baseM * baseN;
    tiling.stepKa = stepKa;
    tiling.stepKb = stepKb;
    tiling.dbL0C = 1;

    size_t tilingSize = sizeof(TCubeTiling);
    void* tilingDevice = nullptr;
    aclrtMalloc(&tilingDevice, tilingSize, ACL_MEM_MALLOC_HUGE_FIRST);
    aclrtMemcpy(tilingDevice, tilingSize, &tiling, tilingSize, ACL_MEMCPY_HOST_TO_DEVICE);

    auto stream = c10_npu::getCurrentNPUStream();
    aclrtlaunch_matmul_custom(usedCoreNum, stream,
        const_cast<void*>(a.storage().data()),
        const_cast<void*>(b.storage().data()),
        const_cast<void*>(c.storage().data()),
        tilingDevice);

    aclrtFree(tilingDevice);
    return c;
}
} // namespace ascendc_path

namespace {
TORCH_LIBRARY_FRAGMENT(npu, m)
{
    m.def("my_matmul(Tensor a, Tensor b) -> Tensor");
}
}

namespace {
TORCH_LIBRARY_IMPL(npu, PrivateUse1, m)
{
    m.impl("my_matmul", TORCH_FN(ascendc_path::run_matmul_custom));
}
